</script>
<template><article class="en-card en-cor"><header class="en-cor-header"><p>COLEGIO DE MONTALBAN</p><h2>Certificate of Registration</h2><p>Academic registration · {{ record.academic_year }} · {{ record.semester }}</p></header><dl class="en-grid"><div><dt>Student number</dt><dd>{{ record.student_number }}</dd></div><div><dt>Student name</dt><dd>{{ record.name }}</dd></div><div><dt>Course / year level</dt><dd>{{ record.course }} / {{ record.year_level }}</dd></div><div><dt>Section</dt><dd>{{ record.section }}</dd></div></dl><div class="en-table"><table><thead><tr><th>Code</th><th>Subject</th><th>Section</th><th>Schedule / room</th><th>Lecture / lab hours</th><th>Units</th></tr></thead><tbody><tr v-for="s in record.subjects" :key="s.id"><td>{{ s.subject_code }}</td><td>{{ s.subject_name }}</td><td>{{ record.section }}</td><td><template v-if="s.schedule">{{ s.schedule.day }} {{ s.schedule.start_time.slice(0,5) }}–{{ s.schedule.end_time.slice(0,5) }}<br>{{ s.schedule.room }}</template><span v-else>Schedule unavailable</span></td><td>{{ s.lecture_hours }} / {{ s.laboratory_hours }}</td><td>{{ s.units }}</td></tr></tbody><tfoot><tr><th colspan="5">Total units</th><td>{{ record.total_units }}</td></tr></tfoot></table></div><p>Registration date: {{ record.enrollment_date }} · Record #{{ record.id }}</p><p>Academic registration information only. Financial assessment and official signatures are not included.</p><button class="en-no-print" @click="print">Print COR</button></article></template>
